use crate::aap::caps::kb_read;

struct Node;

const MAX_QUESTION_CHARS: usize = 512;
const NO_KNOWLEDGE: &str = "No relevant knowledge base entries were found.";

/// Keep at most `max` Unicode scalar values, matching Python's `len` on `str`.
fn bound_chars(s: &str, max: usize) -> String {
    match s.char_indices().nth(max) {
        Some((idx, _)) => s[..idx].to_string(),
        None => s.to_string(),
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let q = query.query;

        // The requires clause bounds the input already. Truncating again keeps
        // the ensures clause true even if that precondition were violated.
        let question = bound_chars(&q.question, MAX_QUESTION_CHARS);

        let mut knowledge: Vec<String> = kb_read::lookup(&question)
            .into_iter()
            .filter(|entry| !entry.trim().is_empty())
            .collect();

        if knowledge.is_empty() {
            knowledge.push(NO_KNOWLEDGE.to_string());
        }

        ConversationContext {
            intent: q.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
